const response = $input.first().json;
const topicData = $('Code: Pick Today\'s Topic').first().json;

// ── Extract Claude text ──
let raw = '';
try {
  raw = response.content[0].text;
} catch(e) {
  raw = '';
  console.log('Claude response error:', JSON.stringify(response));
}

// ── Parse JSON from Claude ──
let blog = null;
try {
  const cleaned = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  blog = JSON.parse(cleaned);
} catch(e) {
  console.log('JSON parse error, using fallback. Raw:', raw.slice(0, 200));
  blog = null;
}

// ── Validate required fields ──
if (!blog || !blog.title || !blog.html_body) {
  const focus = topicData.topic.focus;
  const kw = topicData.topic.keywords[0];
  blog = {
    title: focus.slice(0, 60),
    subtitle: 'Your trusted source in Plainview NY for ' + focus.toLowerCase().slice(0, 60),
    meta_title: focus.slice(0, 60),
    meta_description: 'Visit Long Island Convenience at 605 Old Country Road, Plainview NY for ' + focus.toLowerCase().slice(0,80) + '. Call +1 (917) 338-7086.',
    meta_keywords: topicData.topic.keywords.join(', '),
    tags: ['Long Island', 'Plainview NY', 'Nassau County', topicData.topic.category],
    html_body: '<h2>' + focus + '</h2><p>Looking for ' + kw + '? Visit Long Island Convenience at 605 Old Country Road, Plainview NY 11803. We serve all of Nassau County with same-day pickup available. Call us at +1 (917) 338-7086.</p>',
  };
  console.log('Using fallback blog content.');
}

// ── Ensure tags is an array ──
if (typeof blog.tags === 'string') {
  blog.tags = blog.tags.split(',').map(t => t.trim()).filter(Boolean);
}
if (!Array.isArray(blog.tags)) blog.tags = ['Long Island', 'Plainview NY', 'Nassau County'];

// ── Add Unsplash image to HTML if blog mentions balloons or graduation ──
const cat = topicData.topic.category;
const IMAGES = {
  balloons:      'https://images.unsplash.com/photo-1530103862676-de8c9debad1d?w=900&h=500&fit=crop&auto=format&q=80',
  gift_baskets:  'https://images.unsplash.com/photo-1549465220-1a8b9238cd48?w=900&h=500&fit=crop&auto=format&q=80',
  greeting_cards:'https://images.unsplash.com/photo-1464349095431-e9a21285b5f3?w=900&h=500&fit=crop&auto=format&q=80',
  general:       'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=900&h=500&fit=crop&auto=format&q=80',
};
const imgUrl = IMAGES[cat] || IMAGES.general;
const imgAlt = topicData.topic.focus + ' — Long Island Convenience Plainview NY';
const imgBlock = `<p><img src="${imgUrl}" alt="${imgAlt}" style="max-width:100%;border-radius:8px;margin:16px 0;" /></p>`;

blog.html_body = imgBlock + blog.html_body;

return [{
  json: {
    blog,
    topic: topicData.topic,
    dateStr: topicData.dateStr,
  }
}];

const authResp = $('HTTP: Odoo Authenticate').first().json;
const blogData = $('Code: Parse Claude Response').first().json;

// ── Extract uid from body ──
const uid = authResp?.body?.result?.uid;

// ── Extract session_id from Set-Cookie header ──
// n8n returns headers as an object; set-cookie may be a string or array
let rawCookie = authResp?.headers?.['set-cookie'] || '';
if (Array.isArray(rawCookie)) rawCookie = rawCookie.join('; ');

let sessionId = '';
for (const part of rawCookie.split(';')) {
  const p = part.trim();
  if (p.startsWith('session_id=')) {
    sessionId = p.split('=', 2)[1];
    break;
  }
}

if (!uid || !sessionId) {
  const dump = JSON.stringify(authResp).slice(0, 400);
  throw new Error('Odoo authentication failed. uid=' + uid + ' session=' + sessionId.slice(0,8) + ' Response: ' + dump);
}

console.log('Odoo auth OK. UID:', uid, 'Session:', sessionId.slice(0, 12) + '...');

const b = blogData.blog;
const topic = blogData.topic;

// ── Truncate fields to Odoo limits ──
const title = (b.title || topic.focus).slice(0, 255);
const subtitle = (b.subtitle || '').slice(0, 255);
const metaTitle = (b.meta_title || title).slice(0, 255);
const metaDesc = (b.meta_description || '').slice(0, 400);
const metaKw = (b.meta_keywords || topic.keywords.join(', ')).slice(0, 255);

return [{
  json: {
    sessionId,
    uid,
    odooPayload: {
      "jsonrpc": "2.0",
      "method": "call",
      "id": 2,
      "params": {
        "model": "blog.post",
        "method": "create",
        "args": [{
          "name":                       title,
          "subtitle":                   subtitle,
          "content":                    b.html_body,
          "blog_id":                    topic.blog_id,
          "website_id":                 1,
          "website_published":          true,
          "is_published":               true,
          "website_meta_title":         metaTitle,
          "website_meta_description":   metaDesc,
          "website_meta_keywords":      metaKw,
        }],
        "kwargs": {}
      }
    },
    blogTitle: title,
    blogCategory: topic.category,
    blogBlogId: topic.blog_id,
  }
}];

const createResp  = $('HTTP: Odoo Create Blog Post').first().json;
const readResp    = $('HTTP: Odoo Read Post URL').first().json;
const buildData   = $('Code: Validate Auth + Build Post Payload').first().json;
const blogData    = $('Code: Parse Claude Response').first().json;

// ── Extract post ID from create response ──
const postId = createResp?.result;
if (!postId || typeof postId !== 'number') {
  throw new Error('Blog post creation failed. Odoo response: ' + JSON.stringify(createResp).slice(0, 400));
}
console.log('Blog post created! Odoo ID:', postId);

// ── Get real URL from read response ──
let liveUrl = '';
try {
  const postData = readResp?.result?.[0];
  liveUrl = postData?.website_absolute_url || '';
} catch(e) { liveUrl = ''; }

// Fallback: construct URL from known pattern if read failed
if (!liveUrl) {
  const blogSlugMap = { 3: 'balloons-party-decor-3', 5: 'gift-baskets-gifts-5', 7: 'convenience-grocery-7' };
  const blogSlug   = blogSlugMap[buildData.blogBlogId] || 'our-blog-1';
  const titleSlug  = (buildData.blogTitle || '').toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').slice(0, 80);
  liveUrl = `https://www.longislandconvenience.com/blog/${blogSlug}/${titleSlug}-${postId}`;
  console.log('Used fallback URL construction (read failed)');
}

const gscInspect = `https://search.google.com/search-console/inspect?resource_id=https%3A%2F%2Fwww.longislandconvenience.com%2F&id=${encodeURIComponent(liveUrl)}`;
const gscRequest = 'https://search.google.com/search-console/';

return [{
  json: {
    success:         true,
    postId,
    liveUrl,
    gscInspectUrl:   gscInspect,
    gscDashboard:    gscRequest,
    blogTitle:       buildData.blogTitle,
    blogCategory:    buildData.blogCategory,
    blogBlogId:      buildData.blogBlogId,
    publishedAt:     new Date().toISOString(),
    metaDescription: blogData.blog.meta_description || '',
  }
}];

const result = $input.first().json;

console.log('═══════════════════════════════════════════');
console.log('✅ DAILY BLOG PUBLISHED — LongIslandConvenience.com');
console.log('   Title:    ', result.blogTitle);
console.log('   Category: ', result.blogCategory);
console.log('   Blog ID:  ', result.blogBlogId);
console.log('   Post ID:  ', result.postId);
console.log('   Live URL: ', result.liveUrl);
console.log('   GSC URL:  ', result.gscUrl);
console.log('   Published:', result.publishedAt);
console.log('═══════════════════════════════════════════');

return [{ json: result }];
